import requests
import re
from urllib.parse import urlparse

ALLOWED_DOMAINS = ['example.com']

def crawl(url):
    html = requests.get(url).text
    links = re.findall('href="(.*?)"', html)
    for link in links:
        if is_valid_domain(link):
            crawl(link)

def is_valid_domain(url):
    parsed = urlparse(url)

    if parsed.netloc in ALLOWED_DOMAINS:
        return True
    return False
